const e = $input.first().json;
const fromObject = e.from?.value?.[0] || {};
const from = fromObject.address || e.from || '';
const fromName = fromObject.name || '';
const html = e.textHtml || '';
const plain = e.textPlain || e.text || html.replace(/<[^>]*>/g, ' ');
const redacted = String(plain)
  .replace(/\b\d{6}\b/g, '[可能的验证码已隐藏]')
  .replace(/(api[_-]?key|access[_-]?token|token|password|密码)\s*[:=：]\s*\S+/gi, '$1=[已隐藏]')
  .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[可能的银行卡号已隐藏]')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);
return [{ json: {
  messageId: e.id || e.messageId || '',
  from,
  fromName,
  to: e.to || '',
  subject: e.subject || '（无主题）',
  receivedAt: e.date || new Date().toISOString(),
  content: redacted
} }];

const email = $('整理并脱敏邮件').first().json;
const response = $input.first().json;
let content = response.choices?.[0]?.message?.content ?? response.output_text ?? response.text ?? '';
content = String(content).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let ai;
try {
  ai = JSON.parse(content);
} catch (error) {
  ai = { category: '普通', priority: 'P2', summary: content.slice(0, 80) || '模型返回无法解析', action: '请人工查看原邮件', reason: 'JSON 解析失败' };
}
return [{ json: {
  ...email,
  category: ai.category || '普通',
  priority: ai.priority || 'P2',
  summary: ai.summary || '（无摘要）',
  action: ai.action || '请人工查看',
  reason: ai.reason || '',
  processedAt: new Date().toISOString()
} }];

